                                                                                                                                                                                                                 
  CREATE TABLE "JW_NOTICE"                                                                                                                                                                        
   (	"NOTICE_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 17830 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"TENANT_ID" NUMBER(20,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                             
	"CREATED_BY" NVARCHAR2(256),                                                                                                                                                                                    
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                           
	"UPDATED_BY" NVARCHAR2(256),                                                                                                                                                                                    
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                             
	"TITLE" VARCHAR2(128) NOT NULL ENABLE,                                                                                                                                                                          
	"CONTENT" CLOB,                                                                                                                                                                                                 
	"CONTENT_HTML" CLOB,                                                                                                                                                                                            
	"SOURCE_TYPE" VARCHAR2(20) NOT NULL ENABLE,                                                                                                                                                                     
	"SCOPE_TYPE" VARCHAR2(15) DEFAULT 'ALL' NOT NULL ENABLE,                                                                                                                                                        
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                               
	"NOTICE_TYPE" VARCHAR2(20) DEFAULT 'SYSTEM_NOTICE' NOT NULL ENABLE,                                                                                                                                             
	"IS_NOTIFY" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                              
	 PRIMARY KEY ("NOTICE_ID")                                                                                                                                                                                      
  USING INDEX  ENABLE                                                                                                                                                                                            
   ) ;                                                                                                                                                                                                           

